head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF41101.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/ELWUnderlyingAsset.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listNoELWUnderlyingAsset&inputMessageId=ELW_ASSET_OUT";
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_check_double = function() {
    var url = "/ELWUnderlyingAsset.do?method=checkDoubleELWUnderlyingAsset&inputMessageId=ELW_ASSET_OUT";
    url += "&WRNT_ULY_NM=" + $c.stf.getObjectValue(txb_WRNT_ULY_NM);
    url += "&WRNT_ULY_ENG_NM=" + $c.stf.getObjectValue(txb_WRNT_ULY_ENG_NM);
    dts_CheckDouble.DataID = encodeURI(url);
    dts_CheckDouble.Reset();
};
scwin.fn_Detail = function(row) {
    dts_Uly.setCellData(1, "ISUR_CD", dts_List.getCellData(row, "ISUR_CD"));
    dts_Uly.setCellData(1, "COM_NM", dts_List.getCellData(row, "COM_NM"));
    dts_Uly.setCellData(1, "COM_ENG_NM", dts_List.getCellData(row, "COM_ENG_NM"));
    dts_Uly.setCellData(1, "IDX_TP_NM", dts_List.getCellData(row, "IDX_TP_NM"));
};
scwin.fn_SetHeader = function() {
    dts_Uly.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ELW_ASSET_OUT";
    dts_Uly.reset();
    dts_Uly.insertRow();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_NM, "한글기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_NM, 8, "한글기초자산명")) return false;
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_ENG_NM, "영문기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_ENG_NM, 8, "영문기초자산명")) return false;
    scwin.fn_check_double();
    if (dts_CheckDouble.getTotalRow() > 0) {
        $c.win.alert("이미 동일한 약명이 있습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    var TR_JOB;
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(TR_JOB)) return;
        dts_Uly.setCellData(1, "WRNT_ULY_NM", $c.stf.getObjectValue(txb_WRNT_ULY_NM));
        dts_Uly.setCellData(1, "WRNT_ULY_ENG_NM", $c.stf.getObjectValue(txb_WRNT_ULY_ENG_NM));

        //alert('[dts_Uly]'+dts_Uly.text);
        trs_Save.Action = $c.lc.fn_encodeNSession("/ELWUnderlyingAsset.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveELWUnderlyingAsset");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Uly)";
        trs_Save.Post();
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_Detail(row);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_Uly_OnLoadError = function() {
    $c.stf.alert_error(dts_Uly);
};
scwin.dts_CheckDouble_OnLoadError = function() {
    $c.stf.alert_error(dts_CheckDouble);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(edt_TotalCnt, "총 " + dts_List.getTotalRow() + " 건");
};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    await $c.frame.CloseFrame();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Item);
    scwin.fn_SetHeader();
    scwin.fn_list_sync();
};
